.right-container {
  .header {
    display: flex;
    justify-content: space-between;
    padding: 20px;

    .ivu-btn {
      width: 78px;

      &.upload {
        border-color: #2D8CF0;
        background: #2D8CF0;
        color: #FFFFFF;
      }
    }

    .ivu-radio-wrapper {
      padding: 0 10px;
    }
  }

  .select-wrapper {
    display: inline-block;
    width: 160px;
  }

  .input-wrapper {
    display: inline-block;
    width: 220px;
    margin-right: 14px;
  }

  .main {
    padding: 0 20px;
    min-height: 500px;

    .ivu-table-wrapper {
      margin-bottom: 22px;
    }
  }

  .ivu-table-cell {
    img {
      float: left;
      width: 30px;
      height: 30px;
      object-fit: contain;

      + div {
        margin-left: 50px;
      }
    }
    .table-video {
      float: left;
      width: 30px;
      height: 30px;
      object-fit: contain;

      + div {
        margin-left: 50px;
      }
    }

    .ivu-btn {
      height: auto;
      padding: 0;
      border: 0;
      color: #1890FF;

      &:focus {
        box-shadow: none;
      }

      &:hover {
        background-color: transparent;
      }

      + .ivu-btn {
        margin-left: 10px;
      }
    }
  }
}
